64	 */
65	export interface RekeyResult {
66	  /** The refreshed DID document (PLC data shape) so the home card updates immediately. */
67	  updatedDidDoc: Record<string, unknown>;
68	  /** The new Share 3 envelope (base32/QR form) for the user to save. */
69	  share3: string;
