74	/**
75	 * Build the re-key preview: generate + stage the new recovery share set, prove the account is
76	 * an eligible old-model did:plc identity, and return the additive diff for review.
77	 *
78	 * Idempotent — the staged set is reused across retries. Signs nothing (submit does that).
79	 * Rejects with `SESSION_LOCKED` only downstream in {@link submitRekey}; build touches only the
80	 * public audit log.
81	 */
82	export const buildRekey = (did: string): Promise<RekeyPreview> => invoke('build_rekey_cmd', { did });
83	
84	/**
85	 * Run the re-key: post the additive rotation op (device-key-signed) to plc.directory, escrow
