93	 * On `SESSION_LOCKED`, run {@link sovereignLogin} and retry.
94	 */
95	export const submitRekey = async (did: string): Promise<RekeyResult> => {
96	  await authenticateBiometric('Confirm your recovery-key upgrade');
97	  return invoke('submit_rekey_cmd', { did });
