2	//! In-app, in-memory diagnostics: a small ring buffer of *redacted* network-error
3	//! breadcrumbs the user can export from Settings and hand to support for troubleshooting.
4	//!
5	//! Redaction is by construction. Every recorded field is safe to share: a call-site
6	//! operation name (a fixed vocabulary from the code, never request data), the server
7	//! hostname, an HTTP status, and a short error category or atproto error code. Bearer/DPoP
8	//! tokens, request/response bodies, handles, emails, and DIDs are never captured — so an
9	//! exported report can be shared without leaking account material. Nothing is written to
10	//! disk; the buffer lives for the process lifetime only, and the user initiates every
11	//! export, so there is no passive/always-on collection to opt out of.
12	
13	use std::collections::VecDeque;
14	use std::sync::{Mutex, OnceLock};
15	
16	/// Most breadcrumbs retained; the oldest are dropped FIFO once the buffer is full. Bounded
17	/// so a long session or a failing-server loop can never grow memory without limit.
18	const CAPACITY: usize = 200;
19	
20	/// Whether the failure was the server answering with an error status, or the request never
21	/// producing a usable answer (timeout, connection refused, DNS, a mid-read drop).
22	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
23	pub enum Origin {
24	    /// The server answered with a non-success HTTP status.
25	    Server,
26	    /// A transport failure — the request never yielded a server verdict.
27	    Transport,
28	}
29	
30	impl Origin {
31	    fn label(self) -> &'static str {
32	        match self {
33	            Origin::Server => "server",
34	            Origin::Transport => "transport",
35	        }
36	    }
37	}
38	
39	/// One redacted network-error breadcrumb. Construction is the only redaction gate: callers
40	/// pass structured, non-sensitive values, so there is no free-form field to leak through.
41	#[derive(Clone, Debug)]
42	struct NetworkEvent {
43	    /// RFC 3339 UTC, seconds precision.
44	    at: String,
45	    /// Call-site / operation name, e.g. `"createSession"`.
46	    op: String,
47	    /// Server hostname only — no path, query, or userinfo, e.g. `"plc.directory"`.
48	    host: Option<String>,
49	    origin: Origin,
50	    /// HTTP status, when the server answered.
51	    status: Option<u16>,
