57	/// Process-global breadcrumb sink. A unit-of-global like `IdentityStore`: no state threads
58	/// through the deep network seams (`pds_client`, `plc_monitor`), which record via free
59	/// functions here without carrying a Tauri `State` handle.
60	fn sink() -> &'static Mutex<VecDeque<NetworkEvent>> {
61	    static SINK: OnceLock<Mutex<VecDeque<NetworkEvent>>> = OnceLock::new();
62	    SINK.get_or_init(|| Mutex::new(VecDeque::with_capacity(CAPACITY)))
63	}
