65	fn push(event: NetworkEvent) {
66	    // A poisoned lock must never crash a diagnostics write — recover the guard and continue.
67	    let mut buf = match sink().lock() {
68	        Ok(guard) => guard,
69	        Err(poisoned) => poisoned.into_inner(),
70	    };
71	    if buf.len() == CAPACITY {
72	        buf.pop_front();
73	    }
74	    buf.push_back(event);
75	}
