107	/// Classify a `reqwest` transport error into a short, non-sensitive category. The error's
108	/// `Display` can embed the full request URL (host *and* query), so it is deliberately never
109	/// captured — only this fixed category is.
110	pub fn transport_category(e: &reqwest::Error) -> &'static str {
111	    if e.is_timeout() {
112	        "timeout"
113	    } else if e.is_connect() {
114	        "connect"
115	    } else if e.is_decode() || e.is_body() {
116	        "read"
117	    } else if e.is_request() {
118	        "request"
119	    } else {
120	        "other"
121	    }
122	}
