124	/// Render the recorded breadcrumbs into a shareable plain-text report.
125	pub fn export() -> String {
126	    let events: Vec<NetworkEvent> = {
127	        let buf = match sink().lock() {
128	            Ok(guard) => guard,
129	            Err(poisoned) => poisoned.into_inner(),
130	        };
131	        buf.iter().cloned().collect()
132	    };
133	
134	    let mut out = String::new();
135	    out.push_str("Obsign diagnostics — network events\n");
136	    out.push_str(&format!("Generated: {}\n", now_rfc3339()));
137	    out.push_str(
138	        "Contains operation names, server hostnames, HTTP statuses, and short error codes\n\
139	         only — no tokens, request/response bodies, handles, emails, or DIDs.\n\n",
140	    );
141	
142	    if events.is_empty() {
143	        out.push_str("No network errors have been recorded this session.\n");
144	        return out;
145	    }
146	
147	    out.push_str(&format!("{} event(s), oldest first:\n\n", events.len()));
148	    for e in &events {
149	        let at = &e.at;
150	        let origin = e.origin.label();
151	        let op = &e.op;
152	        let host = e.host.as_deref().unwrap_or("—");
153	        let status = e
154	            .status
155	            .map(|s| s.to_string())
156	            .unwrap_or_else(|| "—".to_string());
157	        let detail = e.detail.as_deref().unwrap_or("");
158	        out.push_str(&format!(
159	            "{at}  {origin:<9}  {op:<26}  {host:<20}  {status:>4}  {detail}\n"
160	        ));
161	    }
162	    out
163	}
