288	/// Read the status, `Retry-After` header, and body off a non-success XRPC response and classify it.
289	///
290	/// The imperative wrapper around [`classify_xrpc_error`]. The `Retry-After` header is captured
291	/// before the body (reading the body consumes the response). The body is bounded to
292	/// [`MAX_XRPC_ERROR_BODY`] so an oversized untrusted payload can't spike memory or flood logs, and
293	/// a mid-read transport failure surfaces as `NetworkError` rather than a fabricated server verdict.
294	/// `context` names the call site (e.g. `"requestPlcOperationSignature"`) for the log line only —
295	/// the returned error carries the server's own message, not the context, so screens show it
296	/// verbatim.
297	async fn classify_xrpc_response(context: &str, resp: reqwest::Response) -> PdsClientError {
298	    let status = resp.status();
299	    // Capture the host before the body read consumes the response — the diagnostics
300	    // breadcrumb records the server hostname only (never the path or query).
301	    let host = resp.url().host_str().map(str::to_string);
302	    let retry_after = resp
303	        .headers()
304	        .get(reqwest::header::RETRY_AFTER)
305	        .and_then(|v| v.to_str().ok())
306	        .map(str::to_string);
307	    let body = match read_body_capped(resp, MAX_XRPC_ERROR_BODY).await {
308	        Ok(body) => body,
309	        Err(e) => {
310	            crate::diagnostics::record_transport(
311	                context,
312	                host.as_deref(),
313	                crate::diagnostics::transport_category(&e),
314	            );
315	            tracing::warn!(context, status = %status, error = %e, "failed to read XRPC error body");
316	            return PdsClientError::NetworkError {
317	                message: format!("failed to read {status} response body: {e}"),
318	            };
319	        }
320	    };
321	    tracing::warn!(context, status = %status, body = %body, "XRPC call returned non-success");
322	    // Redacted breadcrumb for the user-exportable diagnostics log: the atproto `error`
323	    // code is a short, safe token (e.g. `RateLimited`), never the free-form message/body.
324	    let (error_code, _message) = parse_xrpc_error_envelope(&body);
325	    crate::diagnostics::record_server(
326	        context,
327	        host.as_deref(),
328	        status.as_u16(),
329	        error_code.as_deref(),
330	    );
331	    classify_xrpc_error(status.as_u16(), retry_after, &body)
332	}
