1424	/// DNS TXT lookup for `_atproto.{handle}`. Returns `Ok(Some(did))` on success,
1425	/// `Ok(None)` if no matching TXT record found, `Err` on transport failure.
1426	async fn try_resolve_dns(handle: &str) -> Result<Option<String>, PdsClientError> {
1427	    let dns_name = format!("_atproto.{}", handle);
1428	    tracing::debug!(dns_name = %dns_name, "attempting DNS TXT lookup");
1429	
1430	    // Create a resolver using system DNS config (matches PDS pattern in dns.rs:49)
1431	    let resolver = hickory_resolver::Resolver::builder_tokio()
1432	        .map_err(|e| PdsClientError::NetworkError {
1433	            message: format!("failed to create DNS resolver: {}", e),
1434	        })?
1435	        .build()
1436	        .map_err(|e| PdsClientError::NetworkError {
1437	            message: format!("failed to build DNS resolver: {}", e),
1438	        })?;
1439	
1440	    match resolver.txt_lookup(&dns_name).await {
1441	        Ok(lookup) => {
1442	            // Iterate through TXT records and find one starting with "did="
1443	            for record in lookup.answers() {
1444	                let hickory_resolver::proto::rr::RData::TXT(txt) = &record.data else {
1445	                    continue;
1446	                };
1447	                for part in txt.txt_data.iter() {
1448	                    match std::str::from_utf8(part) {
1449	                        Ok(s) => {
1450	                            if let Some(did_value) = s.strip_prefix("did=") {
1451	                                let did = did_value.trim().to_string();
1452	                                tracing::debug!(did = %did, "DNS TXT resolved");
1453	                                return Ok(Some(did));
1454	                            }
1455	                        }
1456	                        Err(_) => {
1457	                            // Non-UTF-8 bytes in TXT record; skip
1458	                        }
1459	                    }
1460	                }
1461	            }
1462	            tracing::debug!(dns_name = %dns_name, "no did= TXT record found");
1463	            Ok(None)
1464	        }
1465	        Err(e) => {
1466	            // Check if it's a "no records found" error (normal for unregistered handles)
1467	            // vs. a transport error (network failure)
1468	            if e.is_no_records_found() {
1469	                tracing::debug!(dns_name = %dns_name, "no DNS TXT records found");
1470	                Ok(None)
1471	            } else {
1472	                tracing::warn!(dns_name = %dns_name, error = %e, "DNS TXT lookup failed");
1473	                Err(PdsClientError::NetworkError {
1474	                    message: format!("DNS lookup failed: {}", e),
1475	                })
1476	            }
1477	        }
1478	    }
1479	}
