1481	/// HTTP well-known fetch. `GET {url}` and return trimmed body on 2xx,
1482	/// `Ok(None)` on 4xx (handle not found), `Err(NetworkError)` on transport or 5xx.
1483	/// The caller constructs the full URL.
1484	async fn try_resolve_http(
1485	    client: &reqwest::Client,
1486	    url: &str,
1487	) -> Result<Option<String>, PdsClientError> {
1488	    tracing::debug!(url = %url, "attempting HTTP well-known lookup");
1489	    match client.get(url).send().await {
1490	        Ok(response) => {
1491	            if response.status().is_success() {
1492	                match response.text().await {
1493	                    Ok(body) => {
1494	                        tracing::debug!(url = %url, did = %body.trim(), "HTTP well-known resolved");
1495	                        Ok(Some(body.trim().to_string()))
1496	                    }
1497	                    Err(e) => {
1498	                        tracing::warn!(url = %url, error = %e, "HTTP well-known body read failed");
1499	                        Err(PdsClientError::NetworkError {
1500	                            message: format!("failed to read response body: {}", e),
1501	                        })
1502	                    }
1503	                }
1504	            } else if response.status().is_client_error() {
1505	                // 4xx = handle not found at this endpoint
1506	                tracing::debug!(url = %url, status = %response.status(), "HTTP well-known not found");
1507	                Ok(None)
1508	            } else {
1509	                // 5xx = temporary server error
1510	                tracing::warn!(url = %url, status = %response.status(), "HTTP well-known server error");
1511	                Err(PdsClientError::NetworkError {
1512	                    message: format!("server error from {}: {}", url, response.status()),
1513	                })
1514	            }
1515	        }
1516	        Err(e) => {
1517	            tracing::warn!(url = %url, error = %e, "HTTP well-known request failed");
1518	            Err(PdsClientError::NetworkError {
1519	                message: format!("HTTP request failed: {}", e),
1520	            })
1521	        }
1522	    }
1523	}
